-- 2) NEW scholarship 1001 (MOFCOM)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (1001, 'MOFCOM Scholarship — CSC Program', 'Ministry of Commerce of the People''s Republic of China (MOFCOM); administered by the China Scholarship Council', 'China', 'Full Funding', 0, 'Applied for through the home-country dispatching authority / application processing agency as a CSC Type A application (Agency Number 00010); annual calls generally run between early January and early April and no single worldwide deadline is published.', '["Master''s","PhD"]', '["All Majors"]', NULL, NULL, false, false, 'The MOFCOM Scholarship — CSC Program is the Chinese Ministry of Commerce''s degree-education channel for recipient (developing) countries, running since 2015 and administered by the China Scholarship Council. It sponsors young and mid-career government officials, senior managerial personnel and academic staff for English-taught master''s programmes of one to two years and doctoral programmes of three years at designated Chinese universities (26 are listed for the programme, including Peking University, Tsinghua, Fudan and Shanghai Jiao Tong), in applied fields such as government, trade, foreign affairs, agriculture, technology, education, culture and health. It is a separate, officials-oriented track from the open Chinese Government Scholarship (record 866): candidates apply as CSC Type A under the MOFCOM agency number 00010 through their home-country dispatching authority rather than by open application to a university. The award is full: tuition and the related academic fees are waived, on-campus accommodation is free, and a monthly stipend of RMB 3,000 (master''s) or RMB 3,500 (doctoral) is paid — expressed in the guide as RMB 36,000 / 42,000 per year — together with a one-off RMB 3,000 resettlement fee, medical insurance, one round-trip international airfare plus limited home-visit fares, and a compulsory annual review that gates each following year of funding.', 'Be a citizen of a developing country other than China and under 45 years old; be in good physical and mental health with a physical examination report issued by a local public hospital (the guide excludes, among others, diseases barred by Chinese entry-exit inspection and quarantine rules, specified severe chronic diseases, recovery period after major surgery or acute disease, severe physical challenge and pregnancy); hold a bachelor''s degree for a master''s programme or a master''s degree for a doctoral programme, with at least three years of working experience; be a public official at division level or above (or corresponding level), senior management staff of an organisation or enterprise, or academic backbone staff of a university or research institution — a background relevant to the programme applied for is preferred; have English sufficient for the programme, stated as equivalent to IELTS 6.0 or TOEFL 80 and above; be committed to promoting friendly exchanges and cooperation between the home country and China; and be neither studying in China nor admitted to another Chinese government scholarship programme. Applications are completed in the CSC online system under Programme Category Type A with Agency Number 00010 and then submitted as the home-country dispatching authority directs; an application with an incorrect agency number is not processed.', 'https://studychina.chinaservicesinfo.com/studychinaapp/scholarship/getById?id=Ss_1010&uniId=UC_00024', '["All"]', 'Government scholarship (China MOFCOM / CSC)', 'Full: tuition, teaching-material, research/survey, English-taught-programme and dissertation-guidance fees waived; free on-campus accommodation; monthly stipend RMB 3,000 (master''s) / RMB 3,500 (doctoral); one-off RMB 3,000 resettlement fee; medical insurance; one round-trip airfare plus up to (n−1) home-visit round trips; compulsory annual review to keep funding.', NULL, NULL, NULL, NULL, 'English equivalent to IELTS 6.0 or TOEFL 80 and above, sufficient for the English-taught programme; the host programme''s academic requirements apply.', '["CSC online application form, printed after submission (Programme Category Type A, Agency Number 00010)","Degree certificates and transcripts (bachelor''s for master''s applicants, master''s for doctoral applicants)","Physical examination report from a local public hospital","Evidence of English proficiency (equivalent to IELTS 6.0 / TOEFL 80 or above)","Further documents as required by the home-country dispatching authority / application processing agency"]', 'https://www.campuschina.org/', NULL, NULL, 'not_published', NULL, NULL, '[]', 'annual', 'Early January to early April (annual call via the home-country dispatching authority)', NULL, 'upcoming', '2026-10-29 21:00:00+05', '2026-10-29 21:00:00+05', 'verified', 9, 'https://studychina.chinaservicesinfo.com/studychinaapp/scholarship/getById?id=Ss_1010&uniId=UC_00024', 'NEW in Enrichment Batch 35 (2026-10-29), written first-hand from the MOFCOM Scholarship-CSC Program guide on CSC''s Study in China service platform (source 3157, fetched 2026-10-29; the page states its information is from the English website of CSC). Reliability is 9 rather than 10 because the read is the platform''s standing programme guide, not a current-year country call: eligibility is recorded exactly as the guide states it (citizens of developing countries other than China, via the home-country dispatching authority), and no Uzbekistan-specific quota or call was read — none is claimed. Stipend rates differ by level (RMB 36,000/yr master''s, RMB 42,000/yr doctoral), so the structured award is NULL / CNY / month / variable with both rates in the text; min_ielts stays NULL because the English bar is phrased as an equivalence tied to programme requirements. Distinct from the open Chinese Government Scholarship (record 866) and its host-university records; do not merge.', true, NULL, NULL, 'CNY', 'month', 'variable');

